/* Lot 110: opacity values, keyframes, @starting-style transitions and inherit (generated by scripts/lot110_gen.py; expectations from scripts/lot110_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[6144];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l110_op_0(void) {
    prep("@keyframes k { 75% { opacity: 1e-1 } } #o { animation-name: j, k; animation-duration: 1000ms; animation-timing-function: linear; animation-composition: replace } #i { opacity: inherit }", 750);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:100%\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.op_animated);
    TEST_ASSERT_EQUAL(0, g_d.op_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@starting-style { #o { opacity: 0.5 } } #o { transition: --x 1s, opacity 2s ease-in } #i { opacity: inherit }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:50%\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:50%\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.op_animated);
    TEST_ASSERT_EQUAL(1, g_d.op_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@keyframes k { 0% { opacity: 1.1510 } 100% { opacity: 2% } } @keyframes j { 50% { opacity: 41% } } #o { opacity: .25; animation: k 1000ms steps(4); animation-composition: replace; animation-timeline: auto, none }", 2330);
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:25%\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.op_animated);
    TEST_ASSERT_EQUAL(0, g_d.op_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
    prep("@keyframes k { from { animation-composition: add; opacity: 100%; animation-timing-function: steps(2) } 50% { opacity: 1.7775 } to { opacity: 0.99999; animation-timing-function: steps(2) } } @keyframes j { 33.33% { opacity: inherit } 100% { opacity: revert; animation-composition: add } } #o { animation: none 2000ms ease-in-out } #i { opacity: 0.5 }", 1126);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"opacity:50%\"", style_of("i"));
    TEST_ASSERT_EQUAL(0, g_d.op_animated);
    TEST_ASSERT_EQUAL(0, g_d.op_transitioned);
    TEST_ASSERT_EQUAL(0, g_d.prop_composed);
}

